  const circuitDefaults={battery:{value:9,internal:.4},resistor:{value:10},rheostat:{value:20},lamp:{value:12},switch:{value:0,closed:true},capacitor:{value:100},inductor:{value:1,internal:.05},diode:{value:.65,reversed:false},ammeter:{value:10},voltmeter:{value:100}};
