    return '<div class="range-block lorentz-param"><div class="range-label"><span>'+labelText+'</span><output data-lorentz-output="'+key+'">'+shown+'</output></div><input type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+value+'" data-lorentz-param="'+key+'" aria-label="'+labelText+' · ползунок"><div class="field"><label>Точный ввод</label><input type="number" min="'+min+'" max="'+max+'" step="any" value="'+value+'" data-lorentz-param="'+key+'" aria-label="'+labelText+'"></div></div>';
