    const leftN=l.fluxDirection===1;ctx.fillStyle=leftN?'#be6259':'#718caf';ctx.fillRect(mx,my,mw/2,mh);ctx.fillStyle=leftN?'#718caf':'#be6259';ctx.fillRect(mx+mw/2,my,mw/2,mh);
    ctx.strokeStyle='#f2bbb0';ctx.strokeRect(mx,my,mw/2,mh);ctx.strokeStyle='#c5d7ea';ctx.strokeRect(mx+mw/2,my,mw/2,mh);
    ctx.fillStyle='#ffe2d5';ctx.textAlign='center';ctx.font='bold 12px var(--sans)';ctx.fillText(leftN?'N':'S',mx+mw*.25,my+22);ctx.fillStyle='#e0eeff';ctx.fillText(leftN?'S':'N',mx+mw*.75,my+22);
