    const magnetDirection=Math.sign(-Math.sin(induction.omega*state.simulationTime));if(state.running&&magnetDirection)drawArrow(ctx,mx+mw*.5,my-17,mx+mw*.5+magnetDirection*37,my-17,'#f2a96c',1.7,6);
    // Витки катушки.
    ctx.strokeStyle='#c9f07a';ctx.lineWidth=2;
    for(let i=0;i<8;i++){const xx=cx-rx+i*gap;ctx.beginPath();ctx.ellipse(xx,cy,9,ry,0,0,Math.PI*2);ctx.stroke();}
    ctx.strokeStyle='#d4e7bd';ctx.beginPath();ctx.moveTo(cx-rx+7*gap,cy-ry);ctx.lineTo(w*.88,cy-ry);ctx.lineTo(w*.88,cy+ry);ctx.lineTo(cx-rx+7*gap,cy+ry);ctx.stroke();
    // Индуцированный ток показан сменой направления при реверсе dΦ/dt.
